import {
    VlMap,
    VlMapBaseLayerGRBGray,
    VlMapDeleteAction,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
} from '@domg-wc/map';

// De features als GeoJSON-object, met coördinaten in Lambert 72 (EPSG:31370): een punt, een lijn en een polygoon.
document.querySelector('vl-map-features-layer').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 1,
            geometry: { type: 'Point', coordinates: [210000, 190000] },
        },
        {
            type: 'Feature',
            id: 2,
            geometry: {
                type: 'LineString',
                coordinates: [
                    [170000, 170000],
                    [150000, 206000],
                ],
            },
        },
        {
            type: 'Feature',
            id: 3,
            geometry: {
                type: 'Polygon',
                coordinates: [
                    [
                        [44000, 171000],
                        [100000, 171000],
                        [100000, 205000],
                        [44000, 205000],
                        [44000, 171000],
                    ],
                ],
            },
        },
    ],
};

// De story zet de property active: die maakt de actie actief, ook als er al een andere actie van de kaart actief is.
// Het attribuut default-active activeert ze enkel als er nog geen andere actie actief is.
document.querySelector('vl-map-delete-action').active = true;

